I.append(R(6372891,"आसान चिकन पानिनी","कुरकुरी ब्रेड, गरम स्वादिष्ट भरावन और पिघले चीज़ वाली एक टोस्टी पानिनी संतोषजनक, मधुमेह के अनुकूल दोपहर का भोजन या हल्का रात का खाना बनाती है। पानिनी को पैन में (कास्ट आयरन यहाँ बहुत अच्छा काम करता है) धीमी आँच पर पकाएँ ताकि ब्रेड को जलाए बिना भरावन पूरी तरह गरम हो जाए। यह मील प्रेप की एक बढ़िया रेसिपी है: सभी सैंडविच पहले से तैयार करें और अलग-अलग फ़ॉइल में लपेट दें, फिर परोसने से ठीक पहले पानिनी को टोस्ट करें। संतुलित, हृदय के लिए लाभकारी भोजन के लिए इस सैंडविच को स्पिनच, एवोकाडो और समर बेरी सलाद जैसे किसी सरल साइड सलाद के साथ परोसें। दोगुना करें: हर्ब्ड टैरागन चिकन विद मशरूम जैसी रेसिपी तैयार करते समय चिकन की दोगुनी मात्रा पकाएँ और बचे हुए चिकन को सप्ताह में बाद में इन झटपट पानिनी बनाने के लिए रख लें! यह रेसिपी लिंडा गैसनहाइमर की The 12-Week Diabetes Cookbook से है।","8","1/2 पानिनी",
["4 बड़े चम्मच लाइट मेयोनेज़","8 स्लाइस (हर एक लगभग 1 औंस की) कुरकुरी साबुत गेहूँ की ब्रेड","1/2 कप ताज़ा टैरागन","4 स्लाइस (कुल 6 औंस) कम वसा वाला स्विस चीज़","16 औंस पका चिकन ब्रेस्ट (कटा हुआ)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 स्प्रे, 0.25 ग्राम जैतून के तेल का स्प्रे"],
["सैंडविच जोड़ें: ब्रेड के 4 स्लाइस में से हर एक पर 1 बड़ा चम्मच मेयोनेज़ लगाएँ। हर एक के ऊपर टैरागन, चीज़ और चिकन डालें, सामग्री को चारों स्लाइस में बराबर बाँटते हुए। हर एक पर नमक और काली मिर्च छिड़कें, फिर हर सैंडविच के ऊपर ब्रेड के बचे स्लाइस रखें।","एक नॉनस्टिक कड़ाही (जो पानिनी रखने के लिए पर्याप्त बड़ी हो) पर जैतून के तेल का स्प्रे करें और धीमी आँच पर गरम करें। पानिनी डालें और ढक्कन या किसी दूसरे साफ़ पैन से दबाएँ। 2 मिनट पकाएँ, पलटें और फिर दबाएँ। 2 मिनट और पकाएँ। (आप पानिनी प्रेस भी इस्तेमाल कर सकते हैं और चीज़ के पिघलने और ब्रेड के सुनहरा होने तक पका सकते हैं।)","हर पानिनी को आधा काटें और हर आधे हिस्से को सलाद के साथ परोसें।"]))
I.append(R(6373822,"भुने जौ और शिमला मिर्च का सूप",None,"6",None,
["3 छोटी गाजर या 2 मध्यम (छिली और चौकोर टुकड़ों में कटी हुई)","1 मध्यम प्याज़ (चौकोर टुकड़ों में कटा हुआ)","¾ कप जल्दी पकने वाला जौ","1 बड़ा चम्मच जैतून का तेल","2 टुकड़े भुने लहसुन वाले चिकन सॉसेज (चौकोर टुकड़ों में कटे हुए)","2 डंठल अजवाइन (सेलरी) (चौकोर टुकड़ों में कटा हुआ)","1 मध्यम लाल शिमला मिर्च (बीज निकाली और चौकोर टुकड़ों में कटी हुई)","1 मध्यम नारंगी या पीली शिमला मिर्च (बीज निकाली और चौकोर टुकड़ों में कटी हुई)","2 कली लहसुन (बारीक कटा हुआ)","4 कप कम सोडियम वाला चिकन शोरबा","14½ औंस कटे हुए टमाटर (कम सोडियम वाले)","1 तेज पत्ता","½ छोटा चम्मच नमक (वैकल्पिक)","¼ छोटा चम्मच काली मिर्च"],
["एक बर्तन में तेल डालकर मध्यम से तेज़ आँच पर रखें। जौ डालें और भुनने तक चलाते रहें, लगभग 2 मिनट। सॉसेज डालें और 2 मिनट और चलाएँ।","प्याज़, अजवाइन, गाजर और शिमला मिर्च डालें और 3 मिनट तक या प्याज़ के पारदर्शी होना शुरू होने तक चलाएँ।","लहसुन डालें और 1 मिनट और चलाएँ।","चिकन शोरबा और टमाटर डालें और चलाएँ।","तेज पत्ता, नमक (वैकल्पिक) और पिसी काली मिर्च डालें। उबाल आने दें, फिर आँच कम करके धीमी आँच पर पकाएँ। ढककर 15 मिनट धीमी आँच पर पकने दें।","तेज पत्ता निकाल दें और सूप परोसें।"]))
I.append(R(6373845,"खीरे के गोलों पर बुलगुर, पुदीना और टमाटर","ये चटपटे छोटे निवाले दोपहर के नाश्ते या झटपट ऐपेटाइज़र के लिए एकदम सही हैं। आप बुलगुर का मिश्रण पहले से बना सकते हैं और परोसने से ठीक पहले इन्हें जोड़ सकते हैं।","4","1/2 कप बुलगुर का मिश्रण और खीरे के 8 स्लाइस",
["1/3 कप जल्दी पकने वाला बुलगुर (सूखा)","1 कप पानी","1 कप ताज़ा पुदीना (बारीक कटा हुआ)","1 मध्यम रोमा (प्लम) टमाटर (छोटे टुकड़ों में कटा हुआ)","1 बड़ा चम्मच नींबू का रस","1 1/2 बड़ा चम्मच कैनोला तेल","1 बड़ा चम्मच सेब का सिरका","1/4 कप लाल प्याज़ (बारीक कटा हुआ)","1/8 छोटा चम्मच कुटी लाल मिर्च के फ़्लेक्स","1/4 छोटा चम्मच नमक","32 स्लाइस खीरा (हर एक लगभग 1/4 इंच मोटा, कुल 12 औंस)"],
["पानी और बुलगुर को एक मध्यम सॉसपैन में तेज़ आँच पर उबालें। आँच कम करें, ढक दें और 12 मिनट धीमी आँच पर पकाएँ।","इस बीच, खीरे को छोड़कर बाकी सामग्री को एक मध्यम कटोरे में मिलाएँ।","बुलगुर को बारीक जाली वाली छन्नी में छानें और जल्दी ठंडा करने के लिए ठंडे पानी के नीचे धोएँ। अतिरिक्त तरल झाड़ दें और टमाटर के मिश्रण में मिलाएँ।"]))
I.append(R(6374972,"बेक की हुई फूलगोभी प्यूरी","यह बेक की हुई फूलगोभी प्यूरी बनाने के लिए हैंड ब्लेंडर का उपयोग करें। यह रसोई का ज़रूरी उपकरण समय और बर्तन बचाने का एक बढ़िया तरीका है। खाने को उसी पैन में प्यूरी करें जिसमें वह पकाया गया था, और सफ़ाई बहुत आसान हो जाती है।","6","1 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 फूलगोभी (फूलों में कटी हुई)","3/4 कप कम सोडियम वाला चिकन शोरबा (बिना वसा वाला, कम सोडियम)","2 बड़े चम्मच Smart Balance ओरिजिनल बटरी स्प्रेड","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/2 छोटा चम्मच काली मिर्च","1/4 कप ताज़ा अजमोद (कटा हुआ, बाँटकर)","3 1/2 बड़े चम्मच परमेसन चीज़ (ताज़ा कद्दूकस किया हुआ)"],
["ओवन को 350 डिग्री पर पहले से गरम करें। 8x8 इंच की बेकिंग डिश पर कुकिंग स्प्रे लगाएँ।","फूलगोभी के फूल, चिकन शोरबा, Smart Balance, नमक और काली मिर्च को एक बड़े सूप के बर्तन में तेज़ आँच पर रखें जब तक तरल उबलना शुरू न हो। आँच को धीमा करें, ढक दें और 10-12 मिनट या काँटे से छेदने पर फूलगोभी के पूरी तरह नरम होने तक भाप में पकाएँ।","इमर्शन ब्लेंडर या फ़ूड प्रोसेसर से फूलगोभी के मिश्रण को चिकना होने तक ब्लेंड करें। दो बड़े चम्मच कटा अजमोद मिलाएँ।","एक छोटे कटोरे में बचे दो बड़े चम्मच अजमोद को कद्दूकस किए चीज़ के साथ मिलाएँ।","प्यूरी की हुई फूलगोभी को तैयार बेकिंग डिश में डालें। ऊपर चीज़ और अजमोद का मिश्रण छिड़कें और 5-7 मिनट या चीज़ के पिघलने और किनारों पर भूरा होना शुरू होने तक बेक करें।"]))
I.append(R(6375634,"गुड मॉर्निंग पावर पारफ़े","एक बेहतरीन नाश्ते का विकल्प, इस रेसिपी में दालचीनी और ग्रेप नट्स इसे साधारण फल और योगर्ट पारफ़े से अलग बनाते हैं।","4","1 पारफ़े, लगभग 1 कप",
["2 कप सादा बिना चर्बी वाला ग्रीक योगर्ट","1 छोटा चम्मच पिसी दालचीनी","1 मध्यम केला","2 1/2 कप स्ट्रॉबेरी (कटी हुई)","1/4 कप ग्रेप-नट-शैली का अनाज (सीरियल)","2 टहनी ताज़ा पुदीना (सजाने के लिए)"],
["दालचीनी, केला और 1 कप योगर्ट को ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें। 4 वाइन या पारफ़े ग्लास में बाँटें।","हर एक के ऊपर ½ कप कटी स्ट्रॉबेरी, बचे योगर्ट का ¼ कप और सीरियल का 1 बड़ा चम्मच डालें। चाहें तो पुदीने की एक टहनी से सजाएँ।"]))
I.append(R(6375867,"स्ट्रॉबेरी और डार्क चॉकलेट के साथ फ़्रोज़न ग्रीक योगर्ट बार्क","स्ट्रॉबेरी और डार्क चॉकलेट के साथ फ़्रोज़न ग्रीक योगर्ट बार्क एक स्वादिष्ट जमी हुई मिठाई है जो ग्रीक योगर्ट की मलाईदारता को स्ट्रॉबेरी की मिठास और गाढ़ी डार्क चॉकलेट के साथ जोड़ती है।","8","2 टुकड़े (~91 ग्राम)",
["2 कप सादा, कम वसा वाला ग्रीक योगर्ट","2 बड़े चम्मच शुगर-फ़्री बहु-उपयोगी सिरप","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1 कप ताज़ी स्ट्रॉबेरी (कटी हुई)","2 औंस डार्क चॉकलेट चिप्स (बिना चीनी मिलाए)"],
["बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","एक कटोरे में ग्रीक योगर्ट, सिरप और वनीला एक्स्ट्रैक्ट मिलाएँ। अच्छी तरह मिलने तक मिलाएँ।","ग्रीक योगर्ट के मिश्रण को तैयार बेकिंग शीट पर डालें और स्पैचुला से एक बराबर परत में फैलाएँ।","कटी स्ट्रॉबेरी और कटी डार्क चॉकलेट को ग्रीक योगर्ट पर बिखेरें।","बेकिंग शीट को फ़्रीज़र में रखें और योगर्ट बार्क को कम से कम 3 घंटे या सख़्त होने तक जमने दें।","जम जाने पर, बार्क को टुकड़ों में तोड़ें। फ़्रीज़र में वायुरोधी डिब्बे में रखें।"]))
I.append(R(6378666,"सब्ज़ी डिप कप","यह बच्चों और बड़ों दोनों के लिए एकदम सही नाश्ता है! सब्ज़ियों और डिप को पहले से एक साथ हिस्सों में बाँटने से हिस्से का आकार नियंत्रित करने में मदद मिलती है, और आप अपने कप में दोबारा डुबो सकते हैं! इन्हें साथ ले जाने के लिए बंद होने वाले कपों में पैक करें, या मेहमानों का स्वागत करते समय सेहतमंद ऐपेटाइज़र के रूप में परोसने के लिए बड़ा बैच बनाएँ। अगर आपके पास सारी सूखी जड़ी-बूटियाँ और मसाले नहीं हैं, तो आप इसकी जगह 1 बड़ा चम्मच रैंच ड्रेसिंग पाउडर मिक्स का उपयोग कर सकते हैं।","4","1 कप सब्ज़ियाँ + 1/4 कप डिप",
["1/4 कप कम वसा वाला छाछ (बटरमिल्क)","1/2 कप सादा बिना चर्बी वाला ग्रीक योगर्ट","1/4 कप लाइट मेयोनेज़","1 बड़ा चम्मच ताज़ा अजमोद (बारीक कटा हुआ)","1/2 छोटा चम्मच सूखा सोआ","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच प्याज़ पाउडर","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","4 कप डुबोने के लिए मिली-जुली सब्ज़ियों की डंडियाँ (गाजर, खीरा, अजवाइन, शिमला मिर्च, आदि)"],
["एक मध्यम कटोरे में छाछ, योगर्ट, मेयोनेज़, अजमोद, सोआ, लहसुन पाउडर, प्याज़ पाउडर, नमक और काली मिर्च मिलाएँ।","डिप का 1/4 भाग प्लास्टिक या काँच के कॉकटेल कप में डालें।","1 कप मिली-जुली सब्ज़ियों की डंडियाँ कप में इस तरह सजाएँ कि सभी डिप को छू रही हों।","बाकी 3 कपों के लिए यही प्रक्रिया दोहराएँ। अगर तुरंत नहीं परोस रहे हैं, तो सब्ज़ियों की डंडियाँ अलग रखें और परोसने से पहले डिप वाले कपों में डालें।"]))
I.append(R(6379140,"बेसिक बीन बर्गर","क्या आप एक स्वादिष्ट, प्रोटीन से भरपूर बर्गर ढूँढ रहे हैं जो बजट के अनुकूल हो और मीटलेस मंडे के लिए एकदम सही हो? क्लासिक का यह सेहतमंद रूप कम खर्चीला है, हृदय के लिए लाभकारी है, और उन चीज़ों से तैयार हो जाता है जो शायद आपके पास पहले से पेंट्री में हों। कम कार्बोहाइड्रेट के साथ ज़्यादा साउथवेस्टर्न स्वाद के लिए, हर बीन बर्गर को लेट्यूस रैप में परोसें, ऊपर 1 बड़ा चम्मच सालसा और एवोकाडो का एक स्लाइस डालकर। यह टैको या बुरीतो के लिए एक बढ़िया मांस-रहित भरावन भी बनाता है। लेकिन अगर आप ज़्यादा क्लासिक स्वाद चाहते हैं, तो इसे साबुत अनाज के बन पर 1 स्लाइस चेडर चीज़, एक बड़े लेट्यूस के पत्ते और टमाटर के मोटे स्लाइस के साथ परोसें।","8","1 बर्गर",
["2 (15-औंस) डिब्बे डिब्बाबंद बीन्स (कोई भी प्रकार) (छनी और धुली हुई)","1/2 कप पीला प्याज़ (बारीक कटा हुआ)","1 कप पका साबुत अनाज जैसे ब्राउन राइस, ओटमील या क्विनोआ","1 बड़ा अंडा","1 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच पिसी काली मिर्च","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["1 1/2 कप बीन्स को प्याज़ के साथ एक बड़े कटोरे में डालें। काँटे या पोटैटो मैशर से लगभग चिकना होने तक मसलें (प्याज़ की वजह से थोड़ा दरदरा रहेगा)। ध्यान दें: अगर आपके पास फ़ूड प्रोसेसर है, तो आप उसे चिकना होने तक ब्लेंड करके कटोरे में डाल सकते हैं।","बाकी बीन्स, पका अनाज, अंडा, लहसुन पाउडर, नमक और काली मिर्च डालें। अच्छी तरह मिलने तक चलाएँ।","बीन के मिश्रण से 8, 1/2 इंच मोटी टिक्कियाँ बनाएँ।","नॉन-स्टिक कड़ाही पर कुकिंग स्प्रे करके मध्यम आँच पर रखें। बीन की टिक्कियाँ डालें और हर तरफ़ लगभग 2-3 मिनट, हल्का भूरा होने तक पकाएँ। अगर आपका पैन सभी 8 बर्गर रखने के लिए पर्याप्त बड़ा नहीं है तो बैच में काम करें।","वायुरोधी डिब्बे में फ़्रिज में 1 सप्ताह तक रखें, या अलग-अलग फ़्रीज़र बैग या डिब्बों में लपेटकर 6 महीने तक फ़्रीज़ करें (केवल पके हुए बर्गर को फ़्रीज़ करें, कच्चे बर्गर को फ़्रीज़ न करें)।"]))
I.append(R(6379199,"खीरा और क्रीम चीज़ बाइट्स","खीरा और क्रीम चीज़ बाइट्स एक ताज़गी भरा और आसानी से बनने वाला ऐपेटाइज़र है जो खीरे के कुरकुरेपन को क्रीम चीज़ की मलाईदार अच्छाई के साथ जोड़ता है। इनकी कुरकुरी बनावट और स्वादों का मेल इन्हें सबकी पसंद बनाता है, और आप अपनी पसंद के अनुसार चेरी टमाटर या मूली के स्लाइस जैसी विभिन्न टॉपिंग के साथ रचनात्मक हो सकते हैं।","4","3 टुकड़े",
["4 औंस लाइट क्रीम चीज़ (बिना वसा वाला)","2 बड़े चम्मच ताज़ा सोआ (बारीक कटा हुआ, सजाने के लिए और)","1/2 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच नींबू का छिलका","1 बड़ा अंग्रेज़ी खीरा (1/4 इंच पतले गोल स्लाइस में कटा हुआ)"],
["एक मिक्सिंग कटोरे में क्रीम चीज़, बारीक कटा ताज़ा सोआ, लहसुन पाउडर और नींबू का छिलका हैंड मिक्सर से फूला होने तक मिलाएँ।","हर खीरे के स्लाइस पर क्रीम चीज़ के मिश्रण की एक उदार मात्रा अच्छी तरह फैलाएँ।","और सोआ से सजाएँ।"]))
I.append(R(6379337,"खीरा ग्वाकामोले","बढ़िया ग्वाक किसे पसंद नहीं? हालाँकि एवोकाडो हमारे लिए बहुत अच्छे हैं और हम उनका रोज़ आनंद ले सकते हैं, हिस्से के आकार का ध्यान रखना ज़रूरी है। जब भी मैं ग्वाकामोले बनाती हूँ, मैं एवोकाडो के साथ किसी सब्ज़ी को मिलाने की कोशिश करती हूँ ताकि मात्रा बढ़े और रेसिपी में एवोकाडो की मात्रा कम हो। खीरा बढ़िया है क्योंकि वह ताज़गी देता है और स्वाद नहीं बदलता। तोरी (ज़ुकिनी) भी बढ़िया रहेगी। कम कार्बोहाइड्रेट वाले नाश्ते या ऐपेटाइज़र के लिए टॉर्टिला चिप्स की जगह कटी मूली या जिकामा के साथ परोसें।","6","1/4 कप",
["1 मध्यम हैस एवोकाडो (गुठली निकाला और चौकोर टुकड़ों में कटा हुआ)","1 मध्यम रोमा (प्लम) टमाटर (छोटे टुकड़ों में कटा हुआ)","1/2 पूरा (लगभग 4 औंस) अंग्रेज़ी (बीज रहित) खीरा (बारीक कटा हुआ)","2 बड़े चम्मच ताज़ी धनिया पत्ती (कटी हुई)","1 बड़ा चम्मच नींबू का रस","1 बड़ा चम्मच सफ़ेद वाइन सिरका","1/2 पूरी जलापेनो मिर्च (बारीक कटी हुई)","1/4 छोटा चम्मच नमक"],
["एक मध्यम कटोरे में एवोकाडो को मोटा-मोटा मसलें। टमाटर, खीरा, धनिया पत्ती, नींबू का रस, सिरका, जलापेनो और नमक डालें और अच्छी तरह मिलने तक मिलाएँ। चाहें तो डुबोने के लिए कटी मूली के साथ परोसें।"]))
save(7,I)
